package com.portfolio.shopsphere.model; import jakarta.persistence.*;import jakarta.validation.constraints.*; @Entity @Table(name="products") public class Product{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@NotBlank String name;@NotBlank String category;@Positive double price;@Min(0) int stock;@Column(length=2000)String description;public Long getId(){return id;}public String getName(){return name;}public void setName(String v){name=v;}public String getCategory(){return category;}public void setCategory(String v){category=v;}public double getPrice(){return price;}public void setPrice(double v){price=v;}public int getStock(){return stock;}public void setStock(int v){stock=v;}public String getDescription(){return description;}public void setDescription(String v){description=v;}}
